cat > "C:/Users/VM Oct26/AppData/Local/Temp/claude/C--Users-User1-Desktop-dark-raiders/8a09e991-b4f4-4b23-b10f-ded92e837fc3/scratchpad/mk-cw-cornercompact2.ps1" <<'EOF'
$g=[IO.File]::ReadAllText($(if($env:MK_SRC){$env:MK_SRC}else{'C:\claudecode\dark raiders\dark_raiders.html'}))
function L([string]$rx){ $m=[regex]::Matches($g,$rx); if($m.Count -ne 1){ throw "anchor $rx matched $($m.Count)" }; return $m[0].Value.Replace("`r",'') }
$a1=L "cw=\(g\.bw-28\)/2, cx=g\.x\+8\+\(i&1\)\*\(cw\+12\);"
$r1="cw=(g.bw-36)/2, cx=g.x+8+(i&1)*(cw+20);   // v33.xx (cw-cornercompact2): 20 between the two columns, so a figure never touches the next label"
$a2=L "trRow\(i\+\+,'','\$'\+TRV\.c\);"
$r2="trRow(i++,'cash','$'+TRV.c);   // v33.xx (cw-cornercompact2): the critic found the money figure with no label read as part of the xp pair; a short word names it"
$chk=@'
  {v:'VER',what:'cw-cornercompact2: the first corner cell is labelled cash and the two columns are 20 apart',
   run:function(){
     if(typeof trRow!=='function'||typeof trColDraw!=='function') return 'SKIP: no corner rows here';
     var src=String(trColDraw)+String(trRow);
     if(src.indexOf("'cash'")<0) return 'the money cell has no cash label';
     if(String(trRow).indexOf('cw+20')<0) return 'the two columns are not 20 apart';
     return null; }},
'@.Replace("`r",'')
$d=[ordered]@{
  title='CORNER BLOCK: CASH LABEL, WIDER GAP'
  why='The picture critic found the unlabelled money figure read as part of the xp pair and the columns were tight. A short cash label and 20 between columns fix it.'
  now='The corner block names the money figure cash and spaces its two columns wider.'
  edits=@( [ordered]@{ anchor=$a1; replacement=$r1 }, [ordered]@{ anchor=$a2; replacement=$r2 } )
  check=$chk
}
[IO.File]::WriteAllText('C:\claudecode\dark raiders\tools\handoff\drafts\draft-cw-cornercompact2.json',($d | ConvertTo-Json -Depth 6),(New-Object Text.UTF8Encoding $false))
'written'
EOF
